def new_pricing(apps, schema_editor):
    """Professional plan: free for the first 10 patients, then NPR 200 per patient. Professionals who already have more than
    10 patients keep them: the extra ones are recorded as pre-paid slots, so nothing stops working."""
    Plan = apps.get_model('billing', 'Plan')
    Patient = apps.get_model('accounts', 'Patient')
    Profile = apps.get_model('accounts', 'ProfessionalProfile')
    Allowance = apps.get_model('billing', 'PatientAllowance')
    Plan.objects.filter(code='professional').update(price_monthly=0, patient_limit=None, price_note='First 10 patients free, then NPR 200 per patient', features=PROFESSIONAL_FEATURES)
    for profile in Profile.objects.all():
        used = Patient.objects.filter(professional=profile, clinic__isnull=True).count()
        Allowance.objects.get_or_create(professional=profile, defaults={'free_limit': 10, 'paid_slots': max(0, used - 10), 'rate': 200})


